// Funções de Formatação
const formatarBRL = (valor) => {
  const n = Number(valor);
  return isNaN(n) ? "R$ 0,00" : n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
};

const formatarPct = (valor) => {
  const n = Number(valor);
  if (isNaN(n)) return "0,00%";
  const sinal = n >= 0 ? "📈 +" : "📉 ";
  return `${sinal}${n.toFixed(2).replace(".", ",")}%`;
};

// Captura dos Dados dos Nós Anteriores
const noCrypto = $("HTTP Request1").first().json;
const noMoedas = $("HTTP Request").first().json;
const noData   = $("Schedule Trigger").first().json;

// Tratamento da Data/Hora
const dia = String(noData["Day of month"]).padStart(2, '0');
const mesNum = noData["Month"]; 
const ano = noData["Year"];
const hora = String(noData["Hour"]).padStart(2, '0');
const minuto = String(noData["Minute"]).padStart(2, '0');

const mesesPT = {
  "January": "Janeiro", "February": "Fevereiro", "March": "Março", 
  "April": "Abril", "May": "Maio", "June": "Junho", 
  "July": "Julho", "August": "Agosto", "September": "Setembro", 
  "October": "Outubro", "November": "Novembro", "December": "Dezembro"
};
const mesTexto = mesesPT[mesNum] || mesNum;

// Retorna apenas os dados puros devidamente tratados
return {
  json: {
    data_formatada: `${dia} de ${mesTexto} de ${ano} às ${hora}:${minuto}`,
    bitcoin: {
      valor: formatarBRL(noCrypto.bitcoin.brl),
      variacao_24h: formatarPct(noCrypto.bitcoin.brl_24h_change)
    },
    dolar: {
      compra: formatarBRL(noMoedas.USDBRL.bid),
      venda: formatarBRL(noMoedas.USDBRL.ask),
      variacao: formatarPct(noMoedas.USDBRL.pctChange)
    },
    euro: {
      compra: formatarBRL(noMoedas.EURBRL.bid),
      venda: formatarBRL(noMoedas.EURBRL.ask),
      variacao: formatarPct(noMoedas.EURBRL.pctChange)
    }
  }
};

